INSERT INTO `attack_scenarios` (`scenario_id`, `name`, `threat_actor`, `description`, `target_environment`, `attack_vector`, `impact`) VALUES
('SCN-APT29-GHOST', 'Operation GhostToken: Hybrid Enterprise Infiltration', 'APT29 / Cozy Bear Archetype', 'Multi-stage intrusion beginning with spearphishing, pivoting through active directory with Kerberoasting, lateral movement via remote WMI, and exfiltrating AWS S3 cloud data through compromised IAM tokens.', 'Hybrid (Windows Domain + AWS Cloud)', 'Spearphishing Attachment -> In-Memory Execution', 'Critical data exfiltration of customer PII and database snapshots from AWS S3'),
('SCN-RANSOM-BLACKCAT', 'Double-Extortion Ransomware Campaign', 'ALPHV / BlackCat Archetype', 'External perimeter compromise via VPN credential stuffing, RDP lateral movement, shadow copy deletion, mass data staging to cloud mega storage, followed by enterprise-wide encryption.', 'Enterprise On-Premise Network', 'VPN Credential Stuffing -> Admin RDP', 'Operational disruption, critical shadow copies wiped, enterprise-wide file encryption'),
('SCN-CLOUD-CRYPTOMINE', 'Cloud-Native IAM Hijack & Compute Hijacking', 'TeamTNT / Cloud Threat Group', 'Compromised developer access key leading to privilege escalation, defense evasion by tampering with CloudTrail, and spinning up high-cost GPU instances for Monero mining.', 'AWS Cloud Infrastructure', 'Leaked Git Credentials -> IAM API Exploitation', 'Mass cloud billing fraud ($45k/day GPU compute), potential infrastructure takeover');
INSERT INTO `mitre_attack_matrix` (`technique_id`, `technique_name`, `tactic`, `tactic_order`, `description`, `detection_guidance`) VALUES
('T1566.001', 'Spearphishing Attachment', 'Initial Access', 1, 'Adversaries send malicious office or compressed attachments to gain initial access.', 'Monitor email gateway detections and office applications spawning command interpreters.'),
('T1133', 'External Remote Services', 'Initial Access', 1, 'Adversaries leverage VPNs, Citrix, or RDP to gain unauthorized network access.', 'Audit unusual geographic login locations, impossible travel, and off-hour VPN connections.'),
('T1059.001', 'PowerShell Execution', 'Execution', 2, 'Adversaries abuse PowerShell to execute arbitrary commands and download payloads.', 'Inspect command line arguments for -enc, -nop, -w hidden, and download cradle functions.'),
('T1047', 'Windows Management Instrumentation', 'Execution', 2, 'Adversaries abuse WMI to execute malicious commands on local or remote endpoints.', 'Monitor wmic.exe process calls and WmiPrvSE.exe spawning unusual child processes.'),
('T1098', 'Account Manipulation', 'Persistence', 3, 'Adversaries manipulate account permissions, credentials, or policies to maintain persistence.', 'Track IAM policy attachments, admin group memberships, and secondary credential generation.'),
('T1078.004', 'Cloud Accounts Compromise', 'Privilege Escalation', 4, 'Adversaries compromise cloud accounts or assume roles with excessive permissions.', 'Correlate AssumeRole API calls from unapproved public IPs and anomalous User-Agents.'),
('T1562.001', 'Disable or Modify Tools', 'Defense Evasion', 5, 'Adversaries disable security software to avoid detection.', 'Monitor service stop requests for WinDefend, CrowdStrike, CarbonBlack, and SentinelOne.'),
('T1562.008', 'Disable Cloud Logs', 'Defense Evasion', 5, 'Adversaries stop cloud logging (CloudTrail, GuardDuty) to blind defenders.', 'Alert immediately on StopLogging, DeleteTrail, or UpdateDetector API calls.'),
('T1490', 'Inhibit System Recovery', 'Defense Evasion', 5, 'Adversaries delete volume shadow copies or backup catalogs to prevent recovery.', 'Alert on vssadmin.exe delete shadows, wbadmin.exe delete catalog, and bcdedit recovery disabled.'),
('T1003.001', 'LSASS Memory Dumping', 'Credential Access', 6, 'Adversaries dump credentials from LSASS process memory.', 'Detect LSASS read access handles from unsigned binaries and procdump usage.'),
('T1558.003', 'Kerberoasting', 'Credential Access', 6, 'Adversaries request Kerberos service tickets for accounts with SPNs to crack hashes offline.', 'Monitor Event ID 4769 with encryption type 0x17 (RC4) requested in high frequency.'),
('T1552.001', 'Credentials In Files', 'Credential Access', 6, 'Adversaries search local file systems for plaintext passwords, tokens, and AWS keys.', 'Track file access to .aws/credentials, id_rsa, and config.json by untrusted processes.'),
('T1046', 'Network Service Discovery', 'Discovery', 7, 'Adversaries scan network IP ranges and ports to identify vulnerable listening services.', 'Detect rapid connection attempts across internal subnets on TCP ports 445, 3389, 22.'),
('T1021.001', 'Remote Desktop Protocol', 'Lateral Movement', 8, 'Adversaries use RDP with compromised credentials to pivot between internal hosts.', 'Track Event ID 4624 (Logon Type 10) between non-jumpbox internal endpoints.'),
('T1530', 'Data from Cloud Storage', 'Collection', 9, 'Adversaries access data stored in cloud object storage systems like AWS S3 or Azure Blobs.', 'Correlate mass GetObject calls on sensitive buckets originating from non-corporate IPs.'),
('T1071.001', 'Web Protocols (C2)', 'Command and Control', 10, 'Adversaries communicate with command and control infrastructure over HTTP/HTTPS.', 'Analyze DNS query periodicity, entropy, and persistent SSL connections to uncategorized domains.'),
('T1048', 'Exfiltration Over Alternative Protocol', 'Exfiltration', 11, 'Adversaries steal sensitive data by transmitting it over covert or public channels.', 'Inspect high-volume egress bandwidth anomalies to unapproved cloud storage or public IPs.'),
('T1567.002', 'Exfiltration to Cloud Storage', 'Exfiltration', 11, 'Adversaries exfiltrate data to public cloud providers like Mega, Dropbox, or OneDrive.', 'Monitor outbound connections and tool execution for mega-cmd, rclone, and file transfer CLIs.'),
('T1486', 'Data Encrypted for Impact', 'Impact', 12, 'Adversaries encrypt enterprise files to interrupt operations and extort victims.', 'High volume rapid file rename events, burst entropy modifications, and ransom note creation.'),
('T1496', 'Resource Hijacking', 'Impact', 12, 'Adversaries hijack computing resources to mine cryptocurrency or conduct attacks.', 'Detect sudden spikes in GPU/CPU utilization and outbound connections to mining pools.');
INSERT INTO `correlation_rules` (`rule_id`, `rule_name`, `description`, `tactic`, `sliding_window_minutes`, `severity`) VALUES
('RULE-PHISH-EXEC', 'Spearphishing Word Document to Process Execution', 'Correlates email gateway attachment download with immediate Office child process creation (cmd/powershell).', 'Execution', 15, 'high'),
('RULE-CRED-LATERAL', 'Credential Access to Remote Lateral Movement', 'Detects LSASS dump or Kerberoasting followed by remote WMI or RDP execution within 60 minutes.', 'Lateral Movement', 60, 'critical'),
('RULE-HYBRID-PIVOT', 'On-Premises Token Theft to Cloud Exfiltration', 'Correlates local file discovery of cloud credentials with anomalous cloud API calls from untrusted IPs.', 'Exfiltration', 120, 'critical'),
('RULE-RANSOM-STAGING', 'Shadow Copy Deletion Followed by Mass Encryption', 'Correlates vssadmin execution with security service termination and file encryption bursts.', 'Impact', 30, 'critical'),
('RULE-CLOUD-HIJACK', 'IAM Escalation Followed by Mass Compute Provisioning', 'Detects privilege policy attachment followed immediately by runaway EC2 instance deployment.', 'Impact', 45, 'critical');
