INSERT INTO `incidents` (`incident_id`, `scenario_id`, `title`, `severity`, `confidence_score`, `status`, `affected_hosts`, `affected_users`, `ai_summary`, `investigation_lead`) VALUES
('INC-2026-001', 'SCN-APT29-GHOST', 'State-Sponsored Intrusion & AWS S3 Exfiltration via GhostToken Campaign', 'critical', 0.94, 'investigating', '["WKSTN-FIN-04", "DC01.corp.local", "AWS-S3-corp-prod-financial-snapshots"]', '["sarah.connor", "svc_sqladmin", "ProductionDataOpsRole"]', 'High-confidence hybrid APT attack sequence detected. Commenced via spearphishing attachment on workstation WKSTN-FIN-04, followed by in-memory LSASS memory dump and Kerberoasting against Domain Controller DC01. Stolen cloud credentials in .aws/credentials were weaponized from foreign IP 185.220.101.5 to assume ProductionDataOpsRole and exfiltrate 1.49 GB of customer financial data.', 'Isolate WKSTN-FIN-04 immediately, rotate svc_sqladmin credentials, revoke AWS STS active sessions for ProductionDataOpsRole, and block external C2 IP 185.220.101.5.'),
('INC-2026-002', 'SCN-RANSOM-BLACKCAT', 'BlackCat Double-Extortion Ransomware Deployment with Shadow Copy Purge', 'critical', 0.98, 'investigating', '["VPN-GW-01", "SRV-FILE-01"]', '["svc_backup"]', 'Attacker performed VPN credential stuffing to access internal file servers via RDP, disabled Volume Shadow Copies via vssadmin, stopped Windows Defender, uploaded financial data to Mega cloud, and initiated file encryption.', 'Sever VPN connection for svc_backup, disconnect SRV-FILE-01 from internal VLAN, and restore file systems from immutable offline backups.'),
('INC-2026-003', 'SCN-CLOUD-CRYPTOMINE', 'Cloud IAM Account Hijacking and Massive GPU Resource Cryptojacking', 'high', 0.91, 'investigating', '["AWS-Account-112233445566", "i-0a88bf2e99d12a"]', '["dev_ci_user"]', 'Compromised developer API key performed unauthorized privilege escalation to AdministratorAccess, disabled CloudTrail logging, and spun up 16 GPU-accelerated EC2 instances running XMRig Monero miner.', 'Revoke dev_ci_user access keys, terminate unauthorized EC2 instances, and re-enable CloudTrail logging.');
